            class $iwC extends Serializable {
              def &lt;init&gt;() = {
                super.&lt;init&gt;;
                ()
              };
              case class A extends scala.Product with scala.Serializable {
                &lt;caseaccessor&gt; &lt;paramaccessor&gt; val a: Int = _;
                def &lt;init&gt;(a: Int) = {
                  super.&lt;init&gt;;
                  ()
                }
              }
            };
            val $iw = new $iwC.&lt;init&gt;
          };
          val $iw = new $iwC.&lt;init&gt;
        };
        val $iw = new $iwC.&lt;init&gt;
      };
      val $iw = new $iwC.&lt;init&gt;
    };
    val $iw = new $iwC.&lt;init&gt;
  };
  val $iw = new $iwC.&lt;init&gt;
}
object $read extends scala.AnyRef {
  def &lt;init&gt;() = {
    super.&lt;init&gt;;
    ()
  };
  val INSTANCE = new $read.&lt;init&gt;
}
defined class A
```

With this patch, it just imports  only the necessary.

```scala

scala&gt; val a = 10l
val a = 10l
a: Long = 10

scala&gt; import a._
import a._
import a._

scala&gt; case class A(a: Int) // show
case class A(a: Int) // show
class $read extends Serializable {
  def &lt;init&gt;() = {
    super.&lt;init&gt;;
    ()
  };
  class $iwC extends Serializable {
    def &lt;init&gt;() = {
      super.&lt;init&gt;;
      ()
    };
    class $iwC extends Serializable {
      def &lt;init&gt;() = {
        super.&lt;init&gt;;
        ()
      };
      case class A extends scala.Product with scala.Serializable {
        &lt;caseaccessor&gt; &lt;paramaccessor&gt; val a: Int = _;
        def &lt;init&gt;(a: Int) = {
          super.&lt;init&gt;;
          ()
        }
      }
    };
    val $iw = new $iwC.&lt;init&gt;
  };
  val $iw = new $iwC.&lt;init&gt;
}
object $read extends scala.AnyRef {
  def &lt;init&gt;() = {
    super.&lt;init&gt;;
    ()
  };
  val INSTANCE = new $read.&lt;init&gt;
}
defined class A

scala&gt;

```

This patch also adds a `:fallback` mode on being enabled it will restore the spark-shell's 1.0.0 behaviour.

